import * as tt from "thinkthen";

// three messages name one team each: billing, shipping,
// and account. The fourth names a parcel and a login, so
// no team reaches 0.9 and it prints null
const options = ["billing", "shipping", "account"];
for (const text of ["Please refund the extra fee on my invoice.",
    "My parcel went to the wrong address.",
    "I cannot reset my password.",
    "My parcel never came, and now I cannot log in to track it."]) {
  console.log(await tt.choose("Which team owns this?",
      text, { options, threshold: 0.9 }));
}
